The Pipe: |&gt;
Read |&gt; as “and then.”

# nested: read inside out
arrange(filter(midwest, state == "WI"), poptotal)

# piped: read top to bottom
midwest |&gt;
  filter(state == "WI") |&gt;
  arrange(poptotal)

To get |&gt; instead of %&gt;% (in RStudio on your machine), go to Tools → Global Options → Code and check Use native pipe operator. This is already enabled in Posit Cloud!

Your Turn: One Way to Do It

# 1
midwest |&gt;
  filter(state == "IL", inmetro == 0) |&gt;
  arrange(desc(percbelowpoverty))

# 2
midwest |&gt;
  select(county, state, starts_with("pop"))

# 3
midwest |&gt;
  mutate(college_nonprof = percollege - percprof)

Your Turn: One Way to Do It

# 1
midwest |&gt; count(state, inmetro)

# 2
midwest |&gt;
  filter(inmetro == 0) |&gt;
  group_by(state) |&gt;
  slice_max(percollege, n = 1)

# 3
midwest |&gt;
  group_by(state) |&gt;
  summarize(metro_share = sum(poptotal[inmetro == 1]) / sum(poptotal))
